#!/usr/bin/env bash
# Local NFS-like persistent root (disposable). Does NOT prove real NFS semantics.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
NFS_ROOT="${CAI_NFS_SIM_ROOT:-/tmp/cai-nfs-sim/cloudera-ai-studio}"
ENV_FILE="${CAI_NFS_ENV_FILE:-$ROOT/.tmp/cai-nfs-sim.env}"

mkdir -p "$(dirname "$ENV_FILE")" "$NFS_ROOT"

cat >"$ENV_FILE" <<EOF
# Generated by scripts/cai/nfs-local-emulation.sh — local path validation only
CAI_DATA_DIR=$NFS_ROOT
STATE_STORE=sqlite
DATABASE_URL=sqlite+pysqlite:///${NFS_ROOT}/metadata/studio.db
DOCUMENT_STORAGE_ROOT=${NFS_ROOT}/documents
SEMANTIC_RUNTIME_STORAGE_ROOT=${NFS_ROOT}/var/semantic-runtime
UVICORN_WORKERS=1
DEPLOYMENT_PROFILE=cai
FEATURE_PROFILE=FULL_ACCELERATOR
QDRANT_URL=${QDRANT_URL:-http://127.0.0.1:6333}
CORS_ORIGINS=http://127.0.0.1:3010,http://localhost:3010
CAI_PREFLIGHT_STRICT=0
CAI_PLATFORM_SEED=1
BANKING_DEMO_PG_PASSWORD=${BANKING_DEMO_PG_PASSWORD:-m1pass}
EOF

echo "NFS sim root: $NFS_ROOT"
echo "Env file: $ENV_FILE"
echo "Use: set -a && source $ENV_FILE && set +a"
